use vstd::prelude::*;

verus! {

    /// concat returns a `Vec<i32>` whose elements are first all of `a` in order,
    /// then all of `b` in order.
    fn concat(a: &[i32], b: &[i32]) -> Vec<i32>
        ensures
            // length matches the sum of the two input slices
            result.len() == a.len() + b.len(),
            // the first `a.len()` elements agree with `a`
            forall |i: usize| i < a.len() ==> result[i] == a[i],
            // the next `b.len()` elements agree with `b`
            forall |j: usize| j < b.len() ==> result[a.len() + j] == b[j],
    {
        // Pre-allocate a vector with enough capacity for both slices
        let mut result = Vec::with_capacity(a.len() + b.len());
        // Copy all elements from the first slice
        result.extend_from_slice(a);
        // Copy all elements from the second slice
        result.extend_from_slice(b);
        result
    }
}

